export default function Section() {
  return (
    <section className="bg-surface">
      <div className="mx-auto max-w-7xl px-4 pt-8 pb-12 sm:px-6 md:pt-12 md:pb-16 lg:px-8">
        <nav aria-label="Breadcrumb" className="flex flex-wrap items-center gap-x-2 gap-y-1 text-xs uppercase tracking-[0.18em] text-foreground-muted">
          <Breadcrumbs>
            {b => (
              <span className="inline-flex items-center gap-2">
                {b.url && !b.current ? (
                  <Link href={b.url} className="inline-flex min-h-[44px] items-center hover:text-foreground">
                    {b.name}
                  </Link>
                ) : (
                  <span aria-current="page" className="inline-flex min-h-[44px] items-center text-foreground">
                    {b.name}
                  </span>
                )}
                {!b.current && <span aria-hidden="true" className="text-border-default">/</span>}
              </span>
            )}
          </Breadcrumbs>
        </nav>

        <Category>
          {c => (
            <div className="mt-6 grid grid-cols-1 gap-8 md:mt-10 lg:grid-cols-12 lg:gap-12">
              <div className="lg:col-span-7">
                <div className="flex flex-wrap items-center gap-3 text-xs font-medium uppercase tracking-[0.2em] text-foreground-muted">
                  <span aria-hidden="true" className="h-1.5 w-1.5 rounded-full bg-accent-700" />
                  {c.parentName && c.parentUrl ? (
                    <Link href={c.parentUrl} className="inline-flex min-h-[44px] items-center gap-1 hover:text-foreground">
                      <Icon name="arrow-left" size="xs" />
                      {c.parentName}
                    </Link>
                  ) : (
                    <span className="inline-flex min-h-[44px] items-center">Shop the range</span>
                  )}
                </div>
                <h1 className="mt-2 break-words font-display text-4xl font-semibold leading-[1.02] tracking-tight text-foreground sm:text-6xl lg:text-7xl">
                  {c.name}
                  <sup className="ml-2 align-super font-sans text-sm font-medium tracking-normal text-accent-700 sm:text-base">
                    {c.productCount}
                  </sup>
                </h1>
                {c.tagline && (
                  <p className="mt-4 max-w-xl text-base text-foreground-secondary md:text-lg">{c.tagline}</p>
                )}
              </div>

              <div className="flex flex-col justify-end gap-6 border-t border-border-default pt-6 lg:col-span-5 lg:border-l lg:border-t-0 lg:pl-10 lg:pt-0">
                {c.image && (
                  <div className="hidden w-32 lg:block">
                    <Image src={c.image} alt={c.name} aspect="1:1" fit="cover" sizes="128px" priority className="rounded-md" />
                  </div>
                )}
                <p className="max-w-md text-base leading-relaxed text-foreground-secondary">
                  {c.description ? c.description : "Take your time and look around. Everything here is picked with care, ready when you are."}
                </p>
                <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-xs uppercase tracking-[0.18em] text-foreground-muted">
                  <span className="text-foreground">
                    <ResultCount />
                  </span>
                  <span aria-hidden="true" className="h-px w-8 bg-border-default" />
                  <Link href="#products" className="inline-flex min-h-[44px] items-center gap-1 text-primary-700 hover:text-primary-800">
                    Start browsing
                    <Icon name="arrow-right" size="xs" />
                  </Link>
                </div>
              </div>
            </div>
          )}
        </Category>

        <hr className="mt-10 border-t border-border-default md:mt-14" />

        <SubCategories className="mt-6 grid grid-cols-3 gap-x-3 gap-y-6 sm:grid-cols-4 md:mt-8 md:grid-cols-6 lg:grid-cols-8 lg:gap-x-5">
          {s => (
            <Link href={s.url} className="group block">
              {s.image ? (
                <Image src={s.image} alt={s.name} aspect="1:1" fit="cover" sizes="(min-width: 1024px) 12vw, (min-width: 768px) 16vw, 33vw" className="rounded-md" />
              ) : (
                <div className="flex aspect-square items-center justify-center rounded-md bg-surface-secondary text-foreground-muted">
                  <Icon name="layers" size="md" strokeWidth={1} />
                </div>
              )}
              <p className="mt-2 text-sm font-medium leading-snug text-foreground underline-offset-4 group-hover:underline sm:text-base">
                {s.name}
              </p>
              <p className="text-xs text-foreground-muted">{s.productCount} items</p>
            </Link>
          )}
        </SubCategories>
      </div>
    </section>
  )
}

export default function Section() {
  return (
    <section className="bg-surface text-foreground">
      <div className="mx-auto max-w-6xl px-4 pt-6 pb-16 sm:px-6 md:pt-8 md:pb-24 lg:px-8">
        <nav aria-label="Breadcrumb" className="text-sm text-foreground-muted">
          <Breadcrumbs className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm text-foreground-muted" />
        </nav>

        <Brand>
          {b => (
            <div className="mt-6 border-t border-border-default pt-10 md:mt-8 md:pt-14">
              <div className="grid grid-cols-1 gap-8 md:grid-cols-12 md:gap-12 lg:gap-16">
                <div className="md:col-span-4 lg:col-span-4">
                  <div className="w-40 sm:w-48 md:w-full">
                    <div className="rounded-md border border-border-default bg-white p-6 sm:p-8">
                      {b.logo ? (
                        <Image
                          src={b.logo}
                          alt={b.name}
                          aspect="1:1"
                          fit="contain"
                          priority
                          sizes="(min-width: 768px) 30vw, 12rem"
                        />
                      ) : (
                        <div className="flex aspect-square items-center justify-center">
                          <Icon name="store" size="xl" strokeWidth={1} className="text-foreground-muted" />
                        </div>
                      )}
                    </div>
                  </div>

                  {(b.founded || b.origin || b.headquarters || b.productCount > 0) && (
                    <dl className="mt-8 hidden divide-y divide-border-default border-y border-border-default md:block">
                      {b.founded && (
                        <div className="flex items-baseline justify-between gap-4 py-3">
                          <dt className="text-xs uppercase tracking-widest text-foreground-muted">Since</dt>
                          <dd className="text-base text-foreground">{b.founded}</dd>
                        </div>
                      )}
                      {b.origin && (
                        <div className="flex items-baseline justify-between gap-4 py-3">
                          <dt className="text-xs uppercase tracking-widest text-foreground-muted">Origin</dt>
                          <dd className="text-right text-base text-foreground">{b.origin}</dd>
                        </div>
                      )}
                      {b.headquarters && (
                        <div className="flex items-baseline justify-between gap-4 py-3">
                          <dt className="text-xs uppercase tracking-widest text-foreground-muted">Based in</dt>
                          <dd className="text-right text-base text-foreground">{b.headquarters}</dd>
                        </div>
                      )}
                      {b.productCount > 0 && (
                        <div className="flex items-baseline justify-between gap-4 py-3">
                          <dt className="text-xs uppercase tracking-widest text-foreground-muted">In store</dt>
                          <dd className="text-base text-foreground">{b.productCount}</dd>
                        </div>
                      )}
                    </dl>
                  )}
                </div>

                <div className="md:col-span-8 lg:col-span-7 lg:col-start-6">
                  <p className="flex items-center gap-2 text-xs font-medium uppercase tracking-widest text-foreground-muted">
                    <span className="inline-block h-1.5 w-1.5 rounded-full bg-accent-700" aria-hidden="true" />
                    The brand
                  </p>

                  <h1 className="mt-4 font-display text-3xl font-semibold leading-tight tracking-tight text-foreground sm:text-4xl lg:text-5xl">
                    {b.name}
                  </h1>

                  {b.tagline && (
                    <p className="mt-4 text-lg leading-relaxed text-foreground-secondary sm:text-xl">
                      {b.tagline}
                    </p>
                  )}

                  {b.description && (
                    <p className="mt-6 max-w-2xl border-l border-accent-700 pl-4 text-base leading-relaxed text-foreground-secondary">
                      {b.description}
                    </p>
                  )}

                  {(b.founded || b.origin || b.headquarters || b.productCount > 0) && (
                    <dl className="mt-8 grid grid-cols-2 gap-x-6 gap-y-4 border-y border-border-default py-4 md:hidden">
                      {b.founded && (
                        <div>
                          <dt className="text-xs uppercase tracking-widest text-foreground-muted">Since</dt>
                          <dd className="mt-1 text-base text-foreground">{b.founded}</dd>
                        </div>
                      )}
                      {b.origin && (
                        <div>
                          <dt className="text-xs uppercase tracking-widest text-foreground-muted">Origin</dt>
                          <dd className="mt-1 text-base text-foreground">{b.origin}</dd>
                        </div>
                      )}
                      {b.headquarters && (
                        <div>
                          <dt className="text-xs uppercase tracking-widest text-foreground-muted">Based in</dt>
                          <dd className="mt-1 text-base text-foreground">{b.headquarters}</dd>
                        </div>
                      )}
                      {b.productCount > 0 && (
                        <div>
                          <dt className="text-xs uppercase tracking-widest text-foreground-muted">In store</dt>
                          <dd className="mt-1 text-base text-foreground">{b.productCount}</dd>
                        </div>
                      )}
                    </dl>
                  )}

                  {(b.website || b.socials.length > 0) && (
                    <div className="mt-8 flex flex-col gap-6 sm:flex-row sm:flex-wrap sm:items-center">
                      {b.website && (
                        <Link
                          href={b.website}
                          target="_blank"
                          className="inline-flex min-h-11 items-center justify-center gap-2 bg-primary-700 px-6 text-sm font-medium uppercase tracking-widest text-white hover:bg-primary-800 sm:justify-start"
                        >
                          Visit website
                          <Icon name="arrow-up-right" size="sm" />
                        </Link>
                      )}

                      {b.socials.length > 0 && (
                        <ul className="flex flex-wrap items-center gap-x-6 gap-y-1">
                          {b.socials.map((s, i) => (
                            <li key={i}>
                              <Link
                                href={s.href}
                                target="_blank"
                                className="inline-flex min-h-11 items-center gap-1 text-sm uppercase tracking-widest text-foreground underline decoration-border-default underline-offset-4 hover:text-accent-700 hover:decoration-accent-700"
                              >
                                {s.label}
                              </Link>
                            </li>
                          ))}
                        </ul>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}
        </Brand>
      </div>
    </section>
  )
}

export default function Card({ p }) {
  return (
    <article className="group relative flex h-full flex-col bg-white">
      <div className="relative overflow-hidden rounded-md bg-surface-secondary">
        <Image
          src={p.image}
          hoverSrc={p.hoverImage}
          alt={p.name}
          aspect="4:5"
          sizes="(min-width: 1024px) 25vw, 50vw"
        />
        <DiscountBadge
          product={p}
          format="minus"
          className="absolute left-2 top-2 rounded-none bg-white px-1.5 py-0.5 text-[11px] font-medium uppercase tracking-wider text-secondary-900"
        />
        <WishlistToggle
          product={p}
          className="absolute right-1 top-1 flex h-11 w-11 items-center justify-center rounded-none text-secondary-900 aria-pressed:text-accent-700 sm:opacity-80 sm:hover:opacity-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-700"
        />
      </div>

      <div className="flex flex-1 flex-col pt-3 sm:pt-4">
        {p.brand || p.category || p.badge ? (
          <div className="mb-1 flex min-w-0 flex-wrap items-center gap-x-2 gap-y-0.5">
            {p.brand || p.category ? (
              <p className="truncate text-[11px] font-medium uppercase tracking-widest text-secondary-600">
                {p.brand || p.category}
              </p>
            ) : null}
            {p.badge ? (
              <span className="inline-flex items-center gap-1 text-[11px] font-medium uppercase tracking-widest text-accent-700">
                <span aria-hidden="true" className="h-1 w-1 rounded-full bg-accent-700"></span>
                {p.badge}
              </span>
            ) : null}
          </div>
        ) : null}

        <h3 className="font-display tracking-tight text-sm font-medium leading-snug text-secondary-900 line-clamp-2">
          <Link
            href={p.url}
            className="after:absolute after:inset-0 after:rounded-md after:content-[''] sm:group-hover:underline sm:group-hover:underline-offset-4 focus-visible:outline-none focus-visible:after:ring-2 focus-visible:after:ring-primary-700 focus-visible:after:ring-offset-2"
          >
            {p.name}
          </Link>
        </h3>

        <RatingStars product={p} count className="mt-1.5 text-xs text-secondary-900" />

        <div className="mt-auto pt-3">
          <div className="flex flex-wrap items-baseline justify-between gap-x-2 gap-y-1 border-t border-secondary-900/10 pt-2">
            <PriceTag product={p} mrp className="text-sm font-semibold text-secondary-900" />
            <StockBadge
              product={p}
              className={p.inStock ? 'text-xs text-secondary-600' : 'text-[11px] font-medium uppercase tracking-wider text-secondary-900 underline underline-offset-2'}
            />
          </div>
          <QuickAdd
            product={p}
            className="mt-2 flex min-h-[44px] w-full items-center justify-center gap-1.5 rounded-none border border-secondary-900 bg-transparent px-2 text-xs font-medium uppercase tracking-wider text-secondary-900 transition-colors sm:mt-3 sm:hover:bg-secondary-900 sm:hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-700 focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:border-secondary-900/20 disabled:text-secondary-600 sm:disabled:hover:bg-transparent sm:disabled:hover:text-secondary-600"
          />
        </div>
      </div>
    </article>
  )
}
